$self.state = $observable({ modelProviderConfig: null, presetProviders: DEFAULT_PROVIDERS })
$self.fetchModelProviders = async () => {
  if ($self.state.modelProviderConfig) return $self.state.modelProviderConfig
  const res = await $chrome.storage.local.get(STORAGE_KEY)
  const list = res && Array.isArray(res[STORAGE_KEY]) ? res[STORAGE_KEY] : []
  $self.state.modelProviderConfig = list
  return list
}
$self.saveModelProviders = async (list) => {
  const plain = JSON.parse(JSON.stringify(list))
  await $chrome.storage.local.set({ [STORAGE_KEY]: plain })
  $self.state.modelProviderConfig = plain
}
$self.showAddOrUpdateProviderDialog = (provider) => {
  const dlg = $self.query(rootEntire + '.addOrUpdateProviderDialog').take()
  if (!dlg) return
  let form
  if (provider) {
    const isCustom = provider.custom !== false
    form = {
      providerSelect: isCustom ? '__custom__' : provider.id,
      providerName: provider.name || '',
      baseUrl: provider.baseUrl || '',
      api: provider.api || 'openai-completions',
      apiKey: provider.apiKey || '',
      models: JSON.parse(JSON.stringify(provider.models || [])),
      custom: isCustom,
      id: provider.id || ''
    }
  } else {
    form = { providerSelect: '__custom__', providerName: '', baseUrl: '', api: 'openai-completions', apiKey: '', models: [], custom: true, id: '' }
  }
  dlg.value = form
  dlg.setComponentProps({ open: true, title: provider ? '修改模型提供方' : '添加模型提供方' })
}
$self.addOrUpdateProvider = async (form) => {
  const list = (await $self.fetchModelProviders()).slice()
  const selectVal = form.providerSelect
  const isEdit = !!form.id
  let id, name, custom
  if (selectVal === '__custom__') {
    custom = true
    name = (form.providerName || '').trim()
    if (!name) { $message.error('提供方名称不能为空'); return false }
    id = isEdit ? form.id : ('custom-' + Date.now().toString(36))
  } else {
    const preset = DEFAULT_PROVIDERS.find((p) => p.id === selectVal)
    if (!preset) { $message.error('提供方无效'); return false }
    if (!isEdit && list.some((p) => p.id === preset.id)) {
      $message.error('该提供方已添加')
      return false
    }
    custom = false
    name = preset.name
    id = preset.id
  }
  const baseUrl = (form.baseUrl || '').trim()
  if (!baseUrl) { $message.error('接口地址不能为空'); return false }
  const models = (form.models || []).map((m) => { const mid = (m.model || '').trim(); return { model: mid } }).filter((m) => m.model)
  const clean = { id, name, baseUrl, api: form.api || 'openai-completions', apiKey: form.apiKey || '', models, custom }
  const existIdx = list.findIndex((p) => p.id === clean.id)
  if (existIdx !== -1) list[existIdx] = clean
  else list.push(clean)
  await $self.saveModelProviders(list)
  $message.success(isEdit ? '修改成功' : '添加成功')
  return true
}
$self.deleteProvider = async (provider) => {
  let list = (await $self.fetchModelProviders()).slice()
  list = list.filter((p) => p.id !== provider.id)
  await $self.saveModelProviders(list)
  $message.success('删除成功')
}

$self.testModel = async (apiKey, baseUrl, api, model) => {
  const key = String(apiKey || '').trim()
  if (!key) return { ok: false, error: '尚未填写 API Key' }
  let endpoint = String(baseUrl || '').trim().replace(/\/+$/, '')
  if (!endpoint) return { ok: false, error: '尚未填写接口地址' }
  const headers = { 'Content-Type': 'application/json' }
  let body
  if (api === 'anthropic-messages') {
    if (!/\/messages$/.test(endpoint)) endpoint += '/messages'
    body = { model, messages: [{ role: 'user', content: '你好' }], temperature: 0.3, max_tokens: 256, stream: false }
    headers['x-api-key'] = key
    headers['anthropic-version'] = '2023-06-01'
  } else if (api === 'openai-responses') {
    if (!/\/responses$/.test(endpoint)) endpoint += '/responses'
    body = { model, input: [{ role: 'user', content: '你好' }], temperature: 0.3, stream: false }
    headers['Authorization'] = 'Bearer ' + key
  } else {
    if (!/\/chat\/completions$/.test(endpoint)) endpoint += '/chat/completions'
    body = { model, messages: [{ role: 'user', content: '你好' }], temperature: 0.3, stream: false }
    headers['Authorization'] = 'Bearer ' + key
  }
  try {
    const res = await $chrome.fetch(endpoint, { method: 'POST', headers, body: JSON.stringify(body) })
    if (!res.ok) {
      let detail = ''
      try { detail = ': ' + (await res.text()).slice(0, 300) } catch (_e) {}
      return { ok: false, error: 'HTTP ' + res.status + detail }
    }
    const data = await res.json()
    let content = null
    if (api === 'anthropic-messages') {
      if (data && Array.isArray(data.content)) content = data.content.map((b) => (b && b.type === 'text' ? b.text : '')).join('')
    } else if (api === 'openai-responses') {
      if (data && Array.isArray(data.output)) content = data.output.filter((o) => o && o.type === 'message' && Array.isArray(o.content)).map((o) => o.content.filter((c) => c && c.type === 'output_text').map((c) => c.text).join('')).join('')
    } else {
      content = data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content
    }
    if (content == null || String(content).trim() === '') return { ok: false, error: '接口未返回有效回复' }
    return { ok: true, content: String(content).trim() }
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) }
  }
}
