}, [rf.state.presetProviders])
$props({
  onChange: (val) => {
    const isCustom = val === '__custom__'
    $self.query(dialogEntire + '.providerName').forEach((f) => { f.visible = isCustom })
    if (isCustom) {
      $self.query(dialogEntire + '.providerName').forEach((f) => { f.value = '' })
      $self.query(dialogEntire + '.baseUrl').forEach((f) => { f.value = '' })
      $self.query(dialogEntire + '.api').forEach((f) => { f.value = 'openai-completions' })
      $self.query(dialogEntire + '.models').forEach((f) => { f.value = [] })
    } else {
      const preset = (rf.state.presetProviders || []).find((p) => p.id === val)
      if (!preset) return
      $self.query(dialogEntire + '.providerName').forEach((f) => { f.value = preset.name })
      $self.query(dialogEntire + '.baseUrl').forEach((f) => { f.value = preset.baseUrl })
      $self.query(dialogEntire + '.api').forEach((f) => { f.value = preset.api })
      $self.query(dialogEntire + '.models').forEach((f) => { f.value = JSON.parse(JSON.stringify(preset.models || [])) })
    }
  }
})

const rf = $utils.getBlockRootField($self)
const dialogKey = 'addOrUpdateProviderDialog'
const dialogEntire = $self.address.entire.substring(0, $self.address.entire.lastIndexOf(dialogKey) + dialogKey.length)
$props({
  onClick: async () => {
    if (!rf) return
    const dlg = rf.query(dialogEntire).take()
    if (!dlg) return
    const form = dlg.value || {}
    const row = $utils.getArrayFieldRow($self, 'ArrayTable')
    const modelVal = (row && (row.model || row.id)) || ''
    if (!modelVal) { $message.error('请先填写模型标识'); return }
    $self.setComponentProps({ loading: true, disabled: true })
    const result = await rf.testModel(form.apiKey, form.baseUrl, form.api, modelVal)
    $self.setComponentProps({ loading: false, disabled: false })
    if (result.ok) $message.success('测试成功：' + (result.content || '').slice(0, 80))
    else $message.error('测试失败：' + result.error)
  }
})
